{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT regexp_extract(message, 'request for \"([^\"]+)\"', 1) AS target, regexp_extract(message, 'nested exception is ([^;]+)', 1) AS cause, count(*) n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' GROUP BY 1,2 ORDER BY n DESC",
          "claim": "Preserve's POST to ts-seat-service /api/v1/seatservice/seats fails with 'Unexpected end of file from server' about 1488 times."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' period, count(*) AS seat_seats_server_spans FROM normal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Server' AND span_name='POST /api/v1/seatservice/seats' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Server' AND span_name='POST /api/v1/seatservice/seats'",
          "claim": "Seat-service's /seats server spans drop from 132 in normal to 0 in abnormal; left_tickets spans are unchanged."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.attr_status_code AS pstatus, c.service_name AS callee, count(*) n, avg(p.duration)/1e6 AS p_ms FROM abnormal_traces p LEFT JOIN abnormal_traces c ON c.parent_span_id = p.span_id WHERE p.service_name='ts-preserve-service' AND p.span_name='POST' GROUP BY ALL ORDER BY n DESC",
          "claim": "Failing preserve client POSTs (about 1497) have no child span and finish in about 1.4 ms, so the request is cut before the callee handles it."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_source, attr_destination, metric, round(sum(value),0) s FROM abnormal_metrics_sum WHERE metric='hubble_drop_total' AND (attr_source LIKE '%preserve%' OR attr_destination LIKE '%seat%') GROUP BY ALL ORDER BY s DESC",
          "claim": "No packet drops on the preserve-to-seat connection; the network counters are at background level, so this is not a network fault."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/preserveservice/preserve' GROUP BY ALL",
          "claim": "Dashboard's preserve requests return Error in 80 of about 101 cases, with p95 about 5 s; the preserve server errors match."
        }
      ]
    }
  ]
}
